SELECT cr.id, cr.post_id, cr.root_comment_id, cr.parent_id, cr.user_id AS userId, cr.reply_to_user_id, cr.content, DATE_FORMAT(cr.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, COALESCE(au.nickname, au.username) AS authorName, au.avatar AS authorAvatar, COALESCE(ru.nickname, ru.username) AS replyToUserName FROM comment_reply cr LEFT JOIN user au ON cr.user_id = au.id LEFT JOIN user ru ON cr.reply_to_user_id = ru.id WHERE cr.post_id = #{postId} AND cr.root_comment_id IN
#{rid}
AND cr.status = 1 ORDER BY cr.create_time ASC
